    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(putAmount >= 1 ether);
        require(address(this).balance >= putAmount);

        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        c.Put{value: putAmount}(unlockTime);

        (uint recordedUnlockTime, uint recordedBalanceBefore) = c.Acc( address(this) );
        require(recordedBalanceBefore == putAmount);
        require(recordedUnlockTime != 0);

        uint cBalMid = address(c).balance;
        uint thisBalMid = address(this).balance;

        require(collectAmount <= recordedBalanceBefore);
        require(collectAmount >= c.MinSum());

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (, uint recordedBalanceAfter) = c.Acc( address(this) );

        if (!reverted) {
            uint expectedBalanceAfter = recordedBalanceBefore - collectAmount;
            assert(
                recordedBalanceAfter == expectedBalanceAfter
                && address(c).balance == cBalMid - collectAmount
                && address(this).balance == thisBalMid + collectAmount
            );
        } else {
            assert(
                recordedBalanceAfter == recordedBalanceBefore
                && address(c).balance == cBalMid
                && address(this).balance == thisBalMid
            );
        }
    }

    receive() external payable {}
}

